FAQ = [["What is GPT-Realtime-2.1?","GPT-Realtime-2.1 is OpenAI's API model for realtime speech-to-speech voice agents with audio, text and image input, text and audio output, configurable reasoning and function calling. It has a 128,000-token context window and 32,000 maximum output tokens."],["How much does GPT-Realtime-2.1 cost?","The standard published rates per million tokens are $4 input, $0.40 cached input and $24 output for text; $32 input, $0.40 cached input and $64 output for audio; and $5 input or $0.50 cached input for images. Mixed-modality sessions use separate rates."],["Does GPT-Realtime-2.1 have a free API tier?","The official model page lists Free as unsupported. API usage and availability depend on your account and usage tier. Check the current OpenAI model page and account limits."],["What is the GPT-Realtime-2.1 context window?","OpenAI lists a 128,000-token context window and a 32,000-token maximum output. Actual available conversation history can shrink as the session grows and may be truncated under configured limits."],["How do I use GPT-Realtime-2.1 in a browser?","Follow OpenAI's Realtime WebRTC guide: create the session or ephemeral client credential on a trusted server, connect the browser using WebRTC, and exchange audio and control events. Never expose a standard OpenAI API key in client-side JavaScript."],["What is the difference between GPT-Realtime-2.1 and GPT-Realtime-2.1 Mini?","Both list 128K context and 32K maximum output. The Mini variant has lower published per-token prices: for example, audio input is $10 versus $32 and audio output $20 versus $64 per million tokens. Choose after testing quality, latency and tool reliability."],["Does GPT-Realtime-2.1 support function calling?","Yes. The official OpenAI model specification lists function calling as supported. Applications still need server-side authorization, tool validation, and safeguards before taking real-world actions."],["Does GPT-Realtime-2.1 support structured outputs, fine-tuning or video?","The official model page lists structured outputs and fine-tuning as unsupported and video as an unsupported modality. Image is input-only."],["Can callers interrupt the model while it speaks?","Yes. Realtime sessions support voice activity detection and interruption handling. Applications should stop playback and manage the unplayed audio in conversation state using documented Realtime events."],["Is GPT-Realtime-2.1 priced per minute?","The model's Realtime API usage is metered by modality-specific tokens, not a universal flat price per voice minute. Cost depends on input and output tokens, conversation history and caching. GPT-Live is a different product with its own session-duration billing."],["Where can I try GPT-Realtime-2.1?","OpenAI's official GPT-Realtime-2.1 model page offers a Try in Playground entry point. Whether you can run a test depends on account access and API setup; this SXF page is a reference, not an embedded Playground."],["Is GPT-Realtime-2.1 the same as ChatGPT Voice?","No. This page describes an OpenAI API model used by developers to build custom voice applications, not a guarantee about which model ChatGPT Voice uses."]]
BODY_HTML = "<section class=\"shell sxf-r21\" data-gpt-realtime21-guide aria-labelledby=\"realtime-guide\">\n<div class=\"sxf-r21-head\">\n  <p class=\"eyebrow\">INDEPENDENT MODEL GUIDE / OFFICIAL OPENAI DOCUMENTATION</p>\n  <h2 id=\"realtime-guide\">GPT-Realtime-2.1 explained: from first voice connection to production cost.</h2>\n  <p class=\"sxf-r21-lead\">GPT-Realtime-2.1 is an OpenAI API model for low-latency, speech-to-speech agents that listen, reason, call tools and speak within an ongoing session. The important engineering choice is not simply the model name: it is how you manage the audio transport, interruptions, tool permissions, and <strong>separate prices for text, audio and images</strong>. This guide uses OpenAI's published specification and documentation checked on October 30, 2026; no independent benchmark or latency measurement is implied.</p>\n  <p><a href=\"https://developers.openai.com/api/docs/models/gpt-realtime-2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Official model specification and Playground entry ↗</a> · <a href=\"https://developers.openai.com/api/docs/pricing\" target=\"_blank\" rel=\"noopener noreferrer\">Official live pricing ↗</a></p>\n</div>\n<nav class=\"sxf-r21-toc\" aria-label=\"On this page\">\n<a href=\"#r21-specs\">Specs</a><a href=\"#r21-pricing\">Pricing</a><a href=\"#r21-cost-example\">Cost example</a><a href=\"#r21-api\">API setup</a><a href=\"#r21-interruptions\">Interruptions</a><a href=\"#r21-mini\">Mini comparison</a><a href=\"#r21-faq\">FAQ</a>\n</nav>\n\n<section class=\"model-deep-section\" id=\"r21-specs\"><div class=\"model-section-head\"><p class=\"eyebrow\">MODEL SPECIFICATIONS</p><h2>What GPT-Realtime-2.1 supports — and what it does not.</h2></div>\n<div class=\"sxf-r21-table-wrap\"><table class=\"sxf-r21-table\">\n<caption>Published GPT-Realtime-2.1 model limits and interface support</caption>\n<thead><tr><th>Property</th><th>Official specification</th><th>Why it matters</th></tr></thead>\n<tbody>\n<tr><th scope=\"row\">API model ID</th><td><code>gpt-realtime-2.1</code></td><td>Specify the exact model in the session configuration.</td></tr>\n<tr><th scope=\"row\">Context window</th><td><strong>128,000 tokens</strong></td><td>Session history consumes context; truncation or summarization policies still matter.</td></tr>\n<tr><th scope=\"row\">Maximum output</th><td><strong>32,000 tokens</strong></td><td>Upper output limit, not an audio-duration guarantee or a default response size.</td></tr>\n<tr><th scope=\"row\">Knowledge cutoff</th><td>September 30, 2024</td><td>Use tools or verified data for later-changing facts.</td></tr>\n<tr><th scope=\"row\">Input</th><td>Text, audio, images</td><td>Voice assistants can receive speech and image inputs.</td></tr>\n<tr><th scope=\"row\">Output</th><td>Text, audio</td><td>No published video-output modality; image generation is not listed.</td></tr>\n<tr><th scope=\"row\">Reasoning</th><td>Configurable reasoning effort</td><td>Increasing effort may increase usage and perceived delay; test the tradeoff.</td></tr>\n<tr><th scope=\"row\">Tool use</th><td>Function calling supported</td><td>Tool results and side effects must be validated by your application.</td></tr>\n<tr><th scope=\"row\">Other features</th><td>Structured outputs and fine-tuning not supported</td><td>Do not assume JSON-schema enforcement or custom model training.</td></tr>\n<tr><th scope=\"row\">Free API tier</th><td>Not supported (official model rate-limit table)</td><td>Account-specific tiers and limits apply.</td></tr>\n</tbody></table></div>\n<p class=\"sxf-r21-note\">The model page's general-purpose <em>Streaming: Not supported</em> feature flag is not a claim that the <strong>Realtime API cannot stream audio</strong>. Realtime audio transport and event handling are documented separately. Verify the endpoint-specific contract rather than assuming ordinary text streaming and Realtime media events are identical.</p>\n</section>\n\n<section class=\"model-deep-section\" id=\"r21-pricing\"><div class=\"model-section-head\"><p class=\"eyebrow\">2026 OFFICIAL TOKEN PRICING</p><h2>GPT-Realtime-2.1 prices: text vs audio vs image.</h2></div>\n<p>Rates below are <strong>USD per 1 million tokens</strong> as published by OpenAI on October 30, 2026, not a per-minute subscription price. Input and output are charged by modality, and cached input may qualify for a lower rate. Recheck the <a href=\"https://developers.openai.com/api/docs/pricing\" target=\"_blank\" rel=\"noopener noreferrer\">source pricing table</a> before budgeting production traffic.</p>\n<div class=\"sxf-r21-table-wrap\"><table class=\"sxf-r21-table\">\n<caption>Standard GPT-Realtime-2.1 pricing, USD per million tokens</caption>\n<thead><tr><th>Modality</th><th>Input</th><th>Cached input</th><th>Output</th></tr></thead><tbody>\n<tr><th scope=\"row\">Text</th><td>$4.00</td><td>$0.40</td><td>$24.00</td></tr>\n<tr><th scope=\"row\">Audio</th><td>$32.00</td><td>$0.40</td><td>$64.00</td></tr>\n<tr><th scope=\"row\">Image</th><td>$5.00</td><td>$0.50</td><td>Not listed</td></tr>\n</tbody></table></div>\n<p>Why the price labels matter: a voice call can contain <strong>incoming audio, generated speech, instructions and text from tools</strong>. Treating everything as $4 per million input text tokens understates the potential bill; using $32 for every token is equally wrong. The existing SXF text-only model calculator deliberately excludes this model from complete voice-session projections.</p>\n</section>\n\n<section class=\"model-deep-section\" id=\"r21-cost-example\"><div class=\"model-section-head\"><p class=\"eyebrow\">REPRODUCIBLE EXAMPLE</p><h2>How to estimate a mixed text-and-audio Realtime API bill.</h2></div>\n<p>For a <strong>hypothetical aggregate usage sample</strong>, assume 1,000 uncached audio input tokens, 2,000 audio output tokens, 400 uncached text input tokens and 300 text output tokens. At the current rates, the illustrative cost is:</p>\n<div class=\"sxf-r21-table-wrap\"><table class=\"sxf-r21-table\"><caption>Illustrative usage arithmetic, excluding cache discounts and non-model charges</caption>\n<thead><tr><th>Usage</th><th>Calculation</th><th>USD</th></tr></thead><tbody>\n<tr><th scope=\"row\">Audio input</th><td>1,000 ÷ 1,000,000 × $32</td><td>$0.0320</td></tr>\n<tr><th scope=\"row\">Audio output</th><td>2,000 ÷ 1,000,000 × $64</td><td>$0.1280</td></tr>\n<tr><th scope=\"row\">Text input</th><td>400 ÷ 1,000,000 × $4</td><td>$0.0016</td></tr>\n<tr><th scope=\"row\">Text output</th><td>300 ÷ 1,000,000 × $24</td><td>$0.0072</td></tr>\n<tr><th scope=\"row\">Total</th><td>Illustrative direct model tokens</td><td><strong>$0.1688</strong></td></tr>\n</tbody></table></div>\n<p>This is <strong>not</strong> a fixed price for one call or one minute: token usage varies by speaking duration, number of responses, model reasoning, transcript content and accumulated conversation history. OpenAI explains that successive Realtime responses may include prior conversation items in their input, so do not count only the newest audio segment. Record actual per-response usage and cached token breakdowns for an estimate grounded in your application. <a href=\"https://developers.openai.com/api/docs/guides/voice-latency-cost\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI usage and caching guide ↗</a>.</p>\n<div class=\"sxf-r21-callout\"><strong>Cost-control checklist:</strong> keep stable instructions and tool definitions when possible to improve cache reuse; avoid unnecessarily long retained conversations; set a sensible truncation policy; and measure end-to-end successful-task cost rather than assuming cached tokens are guaranteed. Changing earlier context can reduce cache hits.</div>\n</section>\n\n<section class=\"model-deep-section\" id=\"r21-api\"><div class=\"model-section-head\"><p class=\"eyebrow\">DEVELOPER IMPLEMENTATION</p><h2>How to start GPT-Realtime-2.1 with WebRTC or WebSocket.</h2></div>\n<p>OpenAI's <a href=\"https://developers.openai.com/api/docs/guides/realtime\" target=\"_blank\" rel=\"noopener noreferrer\">Realtime getting-started guide</a> recommends a browser voice-agent flow with an application server to authorize sessions, a frontend Realtime session, and WebRTC media transport. The server can use <code>POST /v1/realtime/client_secrets</code> to create a short-lived browser credential; another documented integration uses a server-mediated SDP exchange with <code>POST /v1/realtime/calls</code>. In either design, <strong>keep the standard OpenAI API key on your server</strong>, never in public JavaScript.</p>\n<div class=\"sxf-r21-steps\">\n<article><span>01 / AUTHENTICATE</span><h3>Issue limited client access.</h3><p>Require user authentication on your application backend, validate who is allowed to start a voice session, and create a scoped session/client secret. Add abuse controls and log the internal session owner.</p></article>\n<article><span>02 / CONNECT</span><h3>Choose the transport.</h3><p>Use WebRTC in browser/mobile apps where peer audio transport and media devices are native. Use WebSocket when a server or backend agent processes and relays events. SIP or telephony integrations require a separate calling architecture.</p></article>\n<article><span>03 / CONFIGURE</span><h3>Set model, voice and turns.</h3><p>Set <code>type: \"realtime\"</code>, <code>model: \"gpt-realtime-2.1\"</code>, and an output voice in <code>audio.output.voice</code>; manage instructions, tools and turn detection explicitly.</p></article>\n<article><span>04 / OPERATE</span><h3>Handle every turn safely.</h3><p>Track speech-start/stop events, interruption, tool invocations, end-of-turn conditions, authentication failures, reconnects, usage totals and consent or retention rules.</p></article>\n</div>\n<p>A minimal <strong>session configuration shape</strong> from OpenAI's WebRTC documentation (this is a JSON fragment, not a runnable application):</p>\n<pre class=\"sxf-r21-code\"><code>{\n  \"session\": {\n    \"type\": \"realtime\",\n    \"model\": \"gpt-realtime-2.1\",\n    \"audio\": { \"output\": { \"voice\": \"marin\" } }\n  }\n}</code></pre>\n<p>For executable browser and server implementations, follow the current <a href=\"https://developers.openai.com/api/docs/guides/realtime-webrtc\" target=\"_blank\" rel=\"noopener noreferrer\">official WebRTC sample</a> rather than copying old beta events. The GA interface changes token creation and event names, including <code>response.output_audio.delta</code> and <code>response.output_audio_transcript.delta</code>.</p>\n</section>\n\n<section class=\"model-deep-section\" id=\"r21-interruptions\"><div class=\"model-section-head\"><p class=\"eyebrow\">CONVERSATIONAL UX</p><h2>Voice activity detection, barge-in and the limits of low latency.</h2></div>\n<p>OpenAI says GPT-Realtime-2.1 improves alphanumeric recognition, silence and noise handling, and interruption behavior relative to GPT-Realtime-2. This is <strong>a vendor description, not an independent quality score</strong>. Test it on the actual accents, microphones, network conditions, interruptions and domain-specific vocabulary that matter to your users.</p>\n<div class=\"sxf-r21-steps\">\n<article><span>TURN DETECTION</span><h3><code>server_vad</code> vs <code>semantic_vad</code>.</h3><p>Server VAD uses acoustic speech/silence detection; semantic VAD also considers whether the user appears finished. Faster turn-taking may interrupt hesitant speakers; slower turn-taking can feel unresponsive. Tune against realistic conversations.</p></article>\n<article><span>INTERRUPTION</span><h3>Handle user speech during playback.</h3><p>When VAD detects a new turn, the session can cancel an in-progress answer. Your app should stop already-queued audio playback and keep the model's conversation state aligned with what the user actually heard.</p></article>\n<article><span>UNPLAYED OUTPUT</span><h3>Truncate instead of pretending it was spoken.</h3><p>OpenAI documents <code>conversation.item.truncate</code> for removing unheard output audio from session history after interruption. When using WebRTC, audio and control channels must be coordinated.</p></article>\n<article><span>OBSERVABILITY</span><h3>Measure real-world responsiveness.</h3><p>Record capture-to-first-audio latency, p95 turn delay, false speech stops, interruption recovery, tool execution time, successful completion and human escalation. No published universal latency figure substitutes for this evaluation.</p></article>\n</div>\n<p>Relevant documentation: <a href=\"https://developers.openai.com/api/docs/guides/realtime-vad\" target=\"_blank\" rel=\"noopener noreferrer\">Realtime VAD settings</a> and <a href=\"https://developers.openai.com/api/docs/guides/realtime-conversations\" target=\"_blank\" rel=\"noopener noreferrer\">conversation and interruption events</a>.</p>\n</section>\n\n<section class=\"model-deep-section\"><div class=\"model-section-head\"><p class=\"eyebrow\">PRODUCTION DECISIONS</p><h2>Where GPT-Realtime-2.1 fits — and where it does not.</h2></div>\n<div class=\"sxf-r21-steps\">\n<article><span>GOOD FIT TO EVALUATE</span><h3>Interactive service agents.</h3><p>Voice support, appointment intake, interactive tutors, internal knowledge assistants and multimodal workplace tools where low-latency audio and server-approved tool calls matter.</p></article>\n<article><span>NOT A SUBSTITUTE</span><h3>Batch transcription.</h3><p>If you only need speech-to-text for recordings or captions, evaluate specialized transcription endpoints; a conversational speech-to-speech session may add cost and operational complexity.</p></article>\n<article><span>SAFETY FIRST</span><h3>Authorize tool side effects.</h3><p>Require explicit consent or confirmation for consequential actions, limit tool scopes, verify identity before sensitive operations, redact personal data where appropriate, and plan a human handoff.</p></article>\n<article><span>EVALUATION</span><h3>Test real tasks, not just voice charm.</h3><p>Use the same task scripts and noise conditions to compare completion rate, correction burden, understanding of account identifiers, tool accuracy, latency and cost per accepted task.</p></article>\n</div>\n<p>For architecture selection, OpenAI distinguishes an integrated Realtime speech-and-reasoning session from <a href=\"https://developers.openai.com/api/docs/guides/voice-agents\" target=\"_blank\" rel=\"noopener noreferrer\">GPT-Live with a separate backend</a> or a chained speech-to-text → text reasoning → text-to-speech pipeline. Those patterns have different latency, control and billing properties.</p>\n</section>\n\n<section class=\"model-deep-section\" id=\"r21-mini\"><div class=\"model-section-head\"><p class=\"eyebrow\">MODEL SELECTION</p><h2>GPT-Realtime-2.1 vs GPT-Realtime-2.1 Mini.</h2></div>\n<p>Both API model variants support the published speech-agent workflow and show the same listed 128K context/32K output limits. Their public price cards differ materially. The Mini version is a lower-cost option; selecting it for production should depend on your own speech intelligibility, tool accuracy, noise and delay tests, not price alone.</p>\n<div class=\"sxf-r21-table-wrap\"><table class=\"sxf-r21-table\">\n<caption>Official token price comparison, USD per 1 million tokens</caption><thead><tr><th>Property</th><th>GPT-Realtime-2.1</th><th>GPT-Realtime-2.1 Mini</th></tr></thead>\n<tbody>\n<tr><th scope=\"row\">Audio input</th><td>$32.00</td><td>$10.00</td></tr>\n<tr><th scope=\"row\">Audio output</th><td>$64.00</td><td>$20.00</td></tr>\n<tr><th scope=\"row\">Text input</th><td>$4.00</td><td>$0.60</td></tr>\n<tr><th scope=\"row\">Text output</th><td>$24.00</td><td>$2.40</td></tr>\n<tr><th scope=\"row\">Image input</th><td>$5.00</td><td>$0.80</td></tr>\n<tr><th scope=\"row\">Context / max output</th><td>128K / 32K</td><td>128K / 32K</td></tr>\n</tbody></table></div>\n<p>Prices are listed by token category; a lower unit rate does not establish total-session cost without measuring the number of tokens and retries. See the <a href=\"/models/gpt-realtime-2-1-mini/\">SXF Mini model reference</a> and <a href=\"https://developers.openai.com/api/docs/models/gpt-realtime-2.1-mini\" target=\"_blank\" rel=\"noopener noreferrer\">official OpenAI Mini specification</a>.</p>\n</section>\n\n<section class=\"model-deep-section\" id=\"r21-faq\"><div class=\"model-section-head\"><p class=\"eyebrow\">QUESTIONS FROM DEVELOPERS</p><h2>GPT-Realtime-2.1 frequently asked questions.</h2></div>\n<div class=\"sxf-r21-faq\">\n<details><summary>Where can I try GPT-Realtime-2.1 in a Playground?</summary><p>The <a href=\"https://developers.openai.com/api/docs/models/gpt-realtime-2.1\" target=\"_blank\" rel=\"noopener noreferrer\">official OpenAI model page</a> has a Try in Playground entry. API access and usage limits depend on your OpenAI account; SXF is an independent reference and does not run the model here.</p></details>\n<details><summary>Is there a free GPT-Realtime-2.1 API tier?</summary><p>OpenAI's model-page rate-limit table lists the Free tier as unsupported. Check your account's current usage tier before planning a demo.</p></details>\n<details><summary>Is GPT-Realtime-2.1 a per-minute voice model?</summary><p>No: conversational Realtime API use is metered by text, audio and image tokens according to their distinct rates. Do not confuse it with GPT-Live's separately priced session billing.</p></details>\n<details><summary>Does it understand images and video?</summary><p>The model lists image input support, but not video. It can output text and audio, not images or video.</p></details>\n<details><summary>Can GPT-Realtime-2.1 call functions and take actions?</summary><p>Function calling is supported. Any API action must still pass your app's authorization and confirmation checks.</p></details>\n<details><summary>Is standard streaming supported?</summary><p>The model's generic features panel marks Streaming as unsupported, while the Realtime API separately documents realtime audio transport and output events. Use the contract for your chosen endpoint rather than generalizing from a single feature flag.</p></details>\n<details><summary>How do I reduce interruptions and delays?</summary><p>Compare server VAD with semantic VAD, tune the timing and silence settings, monitor playback cancellation, keep tools efficient and measure actual end-to-end latency on representative connections.</p></details>\n<details><summary>Can I use GPT-Realtime-2.1 without exposing my API key?</summary><p>Yes: OpenAI documents server-minted ephemeral client credentials or a server-mediated WebRTC connection. Never bundle a standard OpenAI API key into browser code.</p></details>\n<details><summary>How is it different from GPT-Realtime-2.1 Mini?</summary><p>Mini has lower published rates across key modalities. Evaluate both on speech understanding, tool success, noise recovery and real usage, not theoretical price alone.</p></details>\n</div></section>\n\n<section class=\"model-deep-section\"><div class=\"model-section-head\"><p class=\"eyebrow\">EVIDENCE & UPDATE POLICY</p><h2>Primary sources used for this reference.</h2></div>\n<p>Verified against official OpenAI developer documentation on <time datetime=\"2026-10-30\">October 30, 2026</time>. Prices, limits and platform availability are subject to provider updates. Vendor-stated improvements are identified as such; no fabricated accuracy, benchmark score, median latency or guaranteed search ranking is reported.</p>\n<div class=\"sxf-r21-sources\">\n<a href=\"https://developers.openai.com/api/docs/models/gpt-realtime-2.1\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>GPT-Realtime-2.1 model card</strong><span>Model specs, features, limits and Playground ↗</span></a>\n<a href=\"https://developers.openai.com/api/docs/pricing\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Official OpenAI pricing</strong><span>Text / audio / image Standard rates ↗</span></a>\n<a href=\"https://developers.openai.com/api/docs/guides/realtime\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Realtime getting started</strong><span>Voice architecture, authentication and GA migration ↗</span></a>\n<a href=\"https://developers.openai.com/api/docs/guides/realtime-webrtc\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Realtime with WebRTC</strong><span>Session and ephemeral credential examples ↗</span></a>\n<a href=\"https://developers.openai.com/api/docs/guides/realtime-vad\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Realtime voice activity detection</strong><span>server_vad, semantic_vad and timing ↗</span></a>\n<a href=\"https://developers.openai.com/api/docs/guides/realtime-conversations\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Realtime conversation events</strong><span>Interruptions and playback truncation ↗</span></a>\n<a href=\"https://developers.openai.com/api/docs/guides/voice-latency-cost\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Realtime token accounting</strong><span>History, caching and cost guidance ↗</span></a>\n<a href=\"https://developers.openai.com/api/docs/models/gpt-realtime-2.1-mini\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>GPT-Realtime-2.1 Mini</strong><span>Official model comparison reference ↗</span></a>\n<a href=\"/providers/openai/\"><strong>OpenAI provider directory on SXF</strong><span>Related model references ↗</span></a>\n<a href=\"/guides/ai-agent-security/\"><strong>AI agent security on SXF</strong><span>Production tool authorization and human oversight ↗</span></a>\n</div></section>\n</section>"

def enrich_gpt_realtime_21(page: str, model: dict) -> str:
    """Enrich the generated model reference without changing model catalog values."""
    if model.get("model_id") != "gpt-realtime-2.1":
        raise ValueError("Wrong model for realtime-2.1 editorial renderer")
    if "data-gpt-realtime21-guide" in page:
        raise ValueError("Duplicate GPT-Realtime-2.1 editorial content")
    if page.count("<main>") != 1 or page.count("</main>") != 1:
        raise ValueError("Unexpected model page structure")
    model_id = model["model_id"]
    assert model["sxf_url"] == "/models/gpt-realtime-2-1/"
    assert model["context_window"] == 128000 and model["max_output"] == 32000
    price = model["pricing"]["standard"][-1]
    assert (price["input"], price["cached_input"], price["output"]) == (4, 0.4, 24)
    old_title = '<title>GPT-Realtime-2.1 — API Specs, Context &amp; Pricing | SXF / AI</title>'
    if page.count(old_title) != 1:
        raise ValueError("Generated baseline title unexpectedly changed")
    page = page.replace(old_title, "<title>" + escape(TITLE) + "</title>", 1)
    for field in ('name="description"', 'property="og:description"', 'name="twitter:description"'):
        pat = r'(<meta ' + re.escape(field) + r' content=")[^"]*(" />)'
        page, n = re.subn(pat, lambda m: m.group(1) + escape(DESCRIPTION, quote=True) + m.group(2), page, count=1)
        if n != 1:
            raise ValueError("Missing SEO description: " + field)
    for field in ('property="og:title"', 'name="twitter:title"'):
        pat = r'(<meta ' + re.escape(field) + r' content=")[^"]*(" />)'
        page, n = re.subn(pat, lambda m: m.group(1) + escape(TITLE, quote=True) + m.group(2), page, count=1)
        if n != 1:
            raise ValueError("Missing social title: " + field)
    page = page.replace('<meta property="og:type" content="website" />',
                        '<meta property="og:type" content="article" />', 1)
    original_h1 = '<h1>GPT-Realtime-2.1<br><span>verified model reference.</span></h1>'
    if page.count(original_h1) != 1:
        raise ValueError("Generated heading changed")
    page = page.replace(original_h1, "<h1>" + escape(H1) + "</h1>", 1)
    marker = '<script type="application/ld+json">'
    if page.count(marker) != 1:
        raise ValueError("Expected one JSON-LD script")
    start = page.index(marker) + len(marker)
    end = page.index("</script>", start)
    root = json.loads(page[start:end])
    graph = root["@graph"]
    article = next(node for node in graph if node.get("@type") == "TechArticle")
    article.update({
        "headline": H1,
        "description": DESCRIPTION,
        "dateModified": VERIFIED_ON,
        "mainEntityOfPage": {"@id": CANONICAL + "#webpage"},
        "author": {"@type": "Organization", "name": "VMC Labs",
                   "url": "https://vivamediacreative.com/labs/"},
        "publisher": {"@type": "Organization", "name": "VMC Labs",
                      "url": "https://vivamediacreative.com/labs/"},
        "citation": SOURCES,
        "keywords": ["GPT-Realtime-2.1", "GPT Realtime 2.1 API",
                     "GPT-Realtime-2.1 pricing", "GPT-Realtime-2.1 Playground",
                     "Realtime voice agent", "WebRTC", "speech-to-speech",
                     "GPT-Realtime-2.1 Mini comparison"]
    })
    graph.insert(0, {
        "@type": "WebPage", "@id": CANONICAL + "#webpage",
        "url": CANONICAL, "name": TITLE, "description": DESCRIPTION,
        "isPartOf": {"@id": "https://sxf.si/#website"},
        "mainEntity": {"@id": CANONICAL + "#article"},
        "inLanguage": "en"
    })
    graph.append({
        "@type": "FAQPage", "@id": CANONICAL + "#faq",
        "mainEntityOfPage": {"@id": CANONICAL + "#webpage"},
        "mainEntity": [{"@type": "Question", "name": q,
                        "acceptedAnswer": {"@type": "Answer", "text": a}}
                       for q, a in FAQ]
    })
    schema = json.dumps(root, ensure_ascii=False, separators=(",", ":")).replace("<", "\\u003c")
    page = page[:start] + schema + page[end:]
    page = page.replace("</head>", '<link rel="stylesheet" href="/models/gpt-realtime-2-1/reference.css" />\n</head>', 1)
    page = page.replace("</main>", BODY_HTML + "\n</main>", 1)
    return page
